INSERT INTO agent_eval_cases (id, user_id, title, description, steps_json, supports_random_stock, options_json, sort_order, enabled, created_at, updated_at) VALUES ('turn_plan_stock_price', '', 'TurnPlan · 单轮 · 查股价', '独立 session：查询腾讯控股现价。', '["新 session：运行前清空 Dock Chat","单轮发送：「帮我查一下腾讯控股现在的股价」","verify：校验路由/工具/回复关键词 + LLM 语义评判"]', FALSE, '{"category":"turn_plan","plan_only":false,"session_cleanup":"before_run","dual_model_eval":false,"message":"帮我查一下腾讯控股现在的股价","expect_domain":"stock_analysis","expect_mode":"gather","expect_sop":false,"forbid_tools":["run_strategy_backtest"],"require_tools":["search_code","get_mcp_analysis"],"min_reply_chars":20,"turn_id":"stock_price","dialogue":[{"role":"user","text":"帮我查一下腾讯控股现在的股价","judge":true}],"expect_reply":{"rubric":"应给出腾讯控股的现价或行情信息（价格、涨跌幅等），语气自然。","must_cover":["腾讯"]},"expect_routing":{"domain":"stock_analysis","mode":"gather","sop":false,"require_tools":["search_code","get_mcp_analysis"],"forbid_tools":["run_strategy_backtest"]},"judge":{"enabled":true,"model_slot":"auxiliary","min_score":0.7}}', 50, TRUE, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO agent_eval_cases (id, user_id, title, description, steps_json, supports_random_stock, options_json, sort_order, enabled, created_at, updated_at) VALUES ('turn_plan_stock_technical_chain', '', 'TurnPlan · 多轮 · 查价后看技术面', '同 session：先查腾讯股价，再自然续问技术面/K 线。', '["新 session：运行前清空 Dock Chat","同 session 按序发送：「帮我查一下腾讯控股现在的股价」 → 「再帮我看看腾讯的技术面和K线图」","verify：校验路由/工具/回复关键词 + LLM 语义评判"]', FALSE, '{"category":"turn_plan","plan_only":false,"session_cleanup":"before_run","dual_model_eval":false,"message":"再帮我看看腾讯的技术面和K线图","setup_messages":["帮我查一下腾讯控股现在的股价"],"expect_domain":"stock_analysis","expect_mode":"gather","expect_sop":false,"forbid_tools":["run_strategy_backtest"],"require_tools":["search_code","get_mcp_analysis"],"min_reply_chars":20,"turn_id":"stock_technical_chain","dialogue":[{"role":"user","text":"帮我查一下腾讯控股现在的股价"},{"role":"user","text":"再帮我看看腾讯的技术面和K线图","judge":true}],"expect_reply":{"rubric":"在已查腾讯股价的基础上，应补充技术面/K 线或价格走势分析，而非只重复报价。","must_cover":["腾讯"]},"expect_routing":{"domain":"stock_analysis","mode":"gather","sop":false,"require_tools":["search_code","get_mcp_analysis"],"forbid_tools":["run_strategy_backtest"]},"judge":{"enabled":true,"model_slot":"auxiliary","min_score":0.7}}', 51, TRUE, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO agent_eval_cases (id, user_id, title, description, steps_json, supports_random_stock, options_json, sort_order, enabled, created_at, updated_at) VALUES ('turn_plan_stock_symbol_switch', '', 'TurnPlan · 多轮 · 切换分析标的', '同 session：先分析中际旭创，再明确改聊贵州茅台。', '["新 session：运行前清空 Dock Chat","同 session 按序发送：「帮我分析一下中际旭创」 → 「不聊中际旭创了，帮我分析一下贵州茅台」","verify：校验路由/工具/回复关键词 + LLM 语义评判"]', FALSE, '{"category":"turn_plan","plan_only":false,"session_cleanup":"before_run","dual_model_eval":false,"message":"不聊中际旭创了，帮我分析一下贵州茅台","setup_messages":["帮我分析一下中际旭创"],"expect_domain":"stock_analysis","expect_mode":"gather","expect_sop":false,"forbid_tools":["run_strategy_backtest"],"require_tools":["search_code"],"min_reply_chars":20,"turn_id":"stock_symbol_switch","dialogue":[{"role":"user","text":"帮我分析一下中际旭创"},{"role":"user","text":"不聊中际旭创了，帮我分析一下贵州茅台","judge":true}],"expect_reply":{"rubric":"应识别用户切换到贵州茅台，并给出茅台相关分析或行情，而非继续只聊中际旭创。","must_cover":["茅台"]},"expect_routing":{"domain":"stock_analysis","mode":"gather","sop":false,"require_tools":["search_code"],"forbid_tools":["run_strategy_backtest"]},"judge":{"enabled":true,"model_slot":"auxiliary","min_score":0.7}}', 52, TRUE, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO agent_eval_cases (id, user_id, title, description, steps_json, supports_random_stock, options_json, sort_order, enabled, created_at, updated_at) VALUES ('turn_plan_stock_colloquial_ref', '', 'TurnPlan · 多轮 · 代词指代续问', '同 session：建立中际旭创上下文后，用「它」续问同一标的走势。', '["新 session：运行前清空 Dock Chat","同 session 按序发送：「帮我分析一下中际旭创」 → 「它最近走势怎么样」","verify：校验路由/工具/回复关键词 + LLM 语义评判"]', FALSE, '{"category":"turn_plan","plan_only":false,"session_cleanup":"before_run","dual_model_eval":false,"message":"它最近走势怎么样","setup_messages":["帮我分析一下中际旭创"],"expect_domain":"stock_analysis","expect_mode":"gather","expect_sop":false,"forbid_tools":["run_strategy_backtest"],"require_tools":["search_code"],"min_reply_chars":20,"turn_id":"stock_colloquial_ref","dialogue":[{"role":"user","text":"帮我分析一下中际旭创"},{"role":"user","text":"它最近走势怎么样","judge":true}],"expect_reply":{"rubric":"应理解「它」指代上一轮的中际旭创，并继续给出该标的的走势或行情分析。","must_cover":["中际"]},"expect_routing":{"domain":"stock_analysis","mode":"gather","sop":false,"require_tools":["search_code"],"forbid_tools":["run_strategy_backtest"]},"judge":{"enabled":true,"model_slot":"auxiliary","min_score":0.7}}', 53, TRUE, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO agent_eval_cases (id, user_id, title, description, steps_json, supports_random_stock, options_json, sort_order, enabled, created_at, updated_at) VALUES ('turn_plan_signal_catalog_list', '', 'TurnPlan · 单轮 · 列信号策略', '独立 session：列举可用信号/组合策略，plan 路由 dca_grid/gather 后由模型调 catalog 工具。', '["新 session：运行前清空 Dock Chat","单轮发送：「帮我看看我有哪些信号策略」","verify：校验路由/工具/回复关键词 + LLM 语义评判"]', FALSE, '{"category":"turn_plan","plan_only":false,"session_cleanup":"before_run","dual_model_eval":false,"message":"帮我看看我有哪些信号策略","expect_domain":"dca_grid","expect_mode":"gather","expect_sop":false,"require_tools":["get_signal_combinations"],"min_reply_chars":20,"turn_id":"signal_catalog_list","dialogue":[{"role":"user","text":"帮我看看我有哪些信号策略","judge":true}],"expect_reply":{"rubric":"应列出或摘要用户可用的信号/组合策略，语气自然，不应直接跑回测或 probe。","must_cover":["信号"],"must_not":["开始回测"]},"expect_routing":{"domain":"dca_grid","mode":"gather","sop":false,"require_tools":["get_signal_combinations"]},"judge":{"enabled":true,"model_slot":"auxiliary","min_score":0.7}}', 54, TRUE, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO agent_eval_cases (id, user_id, title, description, steps_json, supports_random_stock, options_json, sort_order, enabled, created_at, updated_at) VALUES ('turn_plan_signal_list_then_probe', '', 'TurnPlan · 多轮 · 列策略后测买卖点', '同 session：先列出可用信号策略，再指定 SAR+MACD 测中际旭创买卖点。', '["新 session：运行前清空 Dock Chat","同 session 按序发送：「帮我看看我有哪些信号策略」 → 「我想用SAR加MACD组合，测一下中际旭创有没有买卖点」","verify：校验路由/工具/回复关键词 + LLM 语义评判"]', FALSE, '{"category":"turn_plan","plan_only":false,"session_cleanup":"before_run","dual_model_eval":false,"message":"我想用SAR加MACD组合，测一下中际旭创有没有买卖点","setup_messages":["帮我看看我有哪些信号策略"],"expect_domain":"signal_probe","expect_mode":"execute","expect_sop":false,"require_tools":["probe_bot_signal_series"],"min_reply_chars":20,"turn_id":"signal_list_then_probe","dialogue":[{"role":"user","text":"帮我看看我有哪些信号策略"},{"role":"user","text":"我想用SAR加MACD组合，测一下中际旭创有没有买卖点","judge":true}],"expect_reply":{"rubric":"在用户已看过策略列表后，应确认 SAR+MACD 组合并对中际旭创做买卖点探测（含买/卖/暂无信号等），不应直接跑完整回测。","must_cover":["中际"],"must_not":["开始回测"]},"expect_routing":{"domain":"signal_probe","mode":"execute","sop":false,"require_tools":["probe_bot_signal_series"]},"judge":{"enabled":true,"model_slot":"auxiliary","min_score":0.7}}', 55, TRUE, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
