INSERT INTO agent_eval_cases (id, user_id, title, description, steps_json, supports_random_stock, options_json, sort_order, enabled, created_at, updated_at) VALUES ('turn_plan_backtest_explicit', '', 'TurnPlan · 单轮 · 显式回测', '独立 session：指定 SAR+MACD 回测小米。', '["新 session：运行前清空 Dock Chat","单轮发送：「帮我用SAR加MACD回测一下小米」","verify：校验路由/工具/回复关键词 + LLM 语义评判"]', FALSE, '{"category":"turn_plan","plan_only":false,"session_cleanup":"before_run","dual_model_eval":false,"message":"帮我用SAR加MACD回测一下小米","expect_domain":"backtest_run","expect_mode":"execute","expect_sop":false,"require_tools":["run_strategy_backtest"],"min_reply_chars":20,"turn_id":"backtest_explicit","dialogue":[{"role":"user","text":"帮我用SAR加MACD回测一下小米","judge":true}],"expect_reply":{"rubric":"应确认 SAR+MACD 回测小米并已发起或汇报回测结果/进度，而非仅做股价查询。","must_cover":["小米","回测"]},"expect_routing":{"domain":"backtest_run","mode":"execute","sop":false,"require_tools":["run_strategy_backtest"]},"judge":{"enabled":true,"model_slot":"auxiliary","min_score":0.7}}', 57, TRUE, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
