INSERT INTO agent_eval_cases (id, user_id, title, description, steps_json, supports_random_stock, options_json, sort_order, enabled, created_at, updated_at) VALUES ('turn_plan_analysis_then_backtest', '', 'TurnPlan · 多轮 · 分析后回测', '同 session：先分析小米，再在同一语境下发起回测。', '["新 session：运行前清空 Dock Chat","同 session 按序发送：「帮我分析一下小米」 → 「接着用SAR加MACD帮小米跑个回测」","verify：校验路由/工具/回复关键词 + LLM 语义评判"]', FALSE, '{"category":"turn_plan","plan_only":false,"session_cleanup":"before_run","dual_model_eval":false,"message":"接着用SAR加MACD帮小米跑个回测","setup_messages":["帮我分析一下小米"],"expect_domain":"backtest_run","expect_mode":"execute","expect_sop":false,"require_tools":["run_strategy_backtest"],"min_reply_chars":20,"turn_id":"analysis_then_backtest","dialogue":[{"role":"user","text":"帮我分析一下小米"},{"role":"user","text":"接着用SAR加MACD帮小米跑个回测","judge":true}],"expect_reply":{"rubric":"在已分析小米的语境下，应发起 SAR+MACD 回测或明确回测执行与结果摘要。","must_cover":["回测"]},"expect_routing":{"domain":"backtest_run","mode":"execute","sop":false,"require_tools":["run_strategy_backtest"]},"judge":{"enabled":true,"model_slot":"auxiliary","min_score":0.7}}', 59, TRUE, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
