INSERT INTO agent_eval_cases (id, user_id, title, description, steps_json, supports_random_stock, options_json, sort_order, enabled, created_at, updated_at) VALUES ('turn_plan_ambiguous_bare_macd', '', 'TurnPlan · 单轮 · 模糊 MACD', '独立 session：无上下文的 MACD 用法问题，应 clarify。', '["新 session：运行前清空 Dock Chat","单轮发送：「这个MACD信号平时该怎么用比较好」","verify：校验路由/工具/回复关键词 + LLM 语义评判"]', FALSE, '{"category":"turn_plan","plan_only":false,"session_cleanup":"before_run","dual_model_eval":false,"message":"这个MACD信号平时该怎么用比较好","expect_domain":"ambiguous","expect_mode":"clarify","expect_sop":false,"forbid_tools":["run_strategy_backtest","probe_bot_signal_series"],"min_reply_chars":20,"turn_id":"ambiguous_bare_macd","dialogue":[{"role":"user","text":"这个MACD信号平时该怎么用比较好","judge":true}],"expect_reply":{"rubric":"应对模糊的 MACD 信号问题给出澄清选项（测点/回测/讲解指标等），不应直接执行回测或测点工具。","must_not":["回测已完成","开始回测"]},"expect_routing":{"domain":"ambiguous","mode":"clarify","sop":false,"forbid_tools":["run_strategy_backtest","probe_bot_signal_series"]},"judge":{"enabled":true,"model_slot":"auxiliary","min_score":0.7}}', 61, TRUE, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
INSERT INTO agent_eval_cases (id, user_id, title, description, steps_json, supports_random_stock, options_json, sort_order, enabled, created_at, updated_at) VALUES ('turn_plan_compound_analysis_backtest', '', 'TurnPlan · 单轮 · 分析+回测复合', '独立 session：一句话含分析与回测，应澄清而非直接执行。', '["新 session：运行前清空 Dock Chat","单轮发送：「帮我把中际旭创分析一下，然后再跑个回测看看效果」","verify：校验路由/工具/回复关键词 + LLM 语义评判"]', FALSE, '{"category":"turn_plan","plan_only":false,"session_cleanup":"before_run","dual_model_eval":false,"message":"帮我把中际旭创分析一下，然后再跑个回测看看效果","expect_domain":"ambiguous","expect_mode":"clarify","expect_sop":false,"forbid_tools":["run_strategy_backtest"],"min_reply_chars":20,"turn_id":"compound_analysis_backtest","dialogue":[{"role":"user","text":"帮我把中际旭创分析一下，然后再跑个回测看看效果","judge":true}],"expect_reply":{"rubric":"一句话同时含分析与回测时，应澄清用户想先做哪一步或分步确认，不应未经确认直接全套执行。"},"expect_routing":{"domain":"ambiguous","mode":"clarify","sop":false,"forbid_tools":["run_strategy_backtest"]},"judge":{"enabled":true,"model_slot":"auxiliary","min_score":0.7}}', 62, TRUE, NOW(), NOW()) ON CONFLICT (id) DO NOTHING;
